  2	 * JSON Export Module
  3	 *
  4	 * Generates JSON snapshots of kspec data for static site hosting.
  5	 * Handles reference resolution, trait expansion, and validation inclusion.
  6	 *
  7	 * AC: @gh-pages-export ac-1, ac-2, ac-3, ac-4, ac-5
  8	 */
  9	
 10	import * as fs from "node:fs/promises";
 11	import * as path from "node:path";
 12	import type { AcceptanceCriterion, InboxItem } from "../schema/index.js";
 13	import {
 14	  AlignmentIndex,
 15	  buildIndexes,
 16	  computeACCoverage,
 17	  initContext,
 18	  loadAllItems,
 19	  loadAllTasks,
 20	  loadInboxItems,
 21	  loadMetaContext,
 22	  loadPlans,
 23	  loadTriageRecords,
 24	  scanTestCoverage,
 25	  type LoadedSpecItem,
 26	  type LoadedTask,
 27	  ReferenceIndex,
 28	  validate,
 29	} from "../parser/index.js";
 30	import { loadSessionContext } from "../parser/meta.js";
 31	import { TraitIndex } from "../parser/traits.js";
 32	import type {
 33	  ExportedItem,
 34	  ExportedTask,
 35	  ExportedValidation,
 36	  ExportStats,
 37	  InheritedAC,
 38	  KspecSnapshot,
 39	} from "./types.js";
 40	
 41	/**
 42	 * Get the kspec version from package.json
 43	 */
 44	async function getKspecVersion(): Promise<string> {
 45	  try {
 46	    // Try to find package.json relative to this module
 47	    const packagePath = path.resolve(
 48	      import.meta.dirname || __dirname,
 49	      "../../package.json"
 50	    );
 51	    const packageJson = JSON.parse(await fs.readFile(packagePath, "utf-8"));
 52	    return packageJson.version || "unknown";
 53	  } catch {
 54	    return "unknown";
 55	  }
 56	}
