 58	/**
 59	 * Resolve spec_ref to its title for display.
 60	 * AC: @gh-pages-export ac-3
 61	 */
 62	function resolveSpecRefTitle(
 63	  specRef: string | null | undefined,
 64	  items: LoadedSpecItem[],
 65	  refIndex: ReferenceIndex
 66	): string | undefined {
 67	  if (!specRef) return undefined;
 68	
 69	  const result = refIndex.resolve(specRef);
 70	  if (!result.ok) return undefined;
 71	
 72	  const item = items.find((i) => i._ulid === result.ulid);
 73	  return item?.title;
 74	}
 75	
 76	/**
 77	 * Expand tasks with resolved spec reference titles.
 78	 * AC: @gh-pages-export ac-3
 79	 */
 80	function expandTasks(
 81	  tasks: LoadedTask[],
 82	  items: LoadedSpecItem[],
 83	  refIndex: ReferenceIndex
 84	): ExportedTask[] {
 85	  return tasks.map((task) => {
 86	    const exportedTask: ExportedTask = { ...task };
 87	
 88	    if (task.spec_ref) {
 89	      const title = resolveSpecRefTitle(task.spec_ref, items, refIndex);
 90	      if (title) {
 91	        exportedTask.spec_ref_title = title;
 92	      }
 93	    }
 94	
 95	    return exportedTask;
 96	  });
 97	}
