188	function normalizeRef(ref: string | null | undefined): string | null {
189	  if (!ref) return null;
190	  return ref.startsWith("@") ? ref.slice(1) : ref;
191	}
192	
193	function matchesTaskPlan(task: LoadedTask, planRef: string): boolean {
194	  const normalizedPlanRef = normalizeRef(planRef);
195	  const normalizedTaskPlan = normalizeRef(task.plan_ref);
196	
197	  if (!normalizedPlanRef || !normalizedTaskPlan) return false;
198	  return (
199	    normalizedTaskPlan === normalizedPlanRef ||
200	    normalizedTaskPlan.toUpperCase().startsWith(normalizedPlanRef.toUpperCase())
201	  );
202	}
203	
204	function countTaskProgress(tasks: LoadedTask[]) {
205	  return tasks.reduce(
206	    (counts, task) => {
207	      counts.total += 1;
208	      switch (task.status) {
209	        case "completed":
210	          counts.completed += 1;
211	          break;
212	        case "in_progress":
213	        case "pending_review":
214	        case "needs_work":
215	          counts.in_progress += 1;
216	          break;
217	        case "blocked":
218	          counts.blocked += 1;
219	          break;
220	        default:
221	          counts.pending += 1;
222	          break;
223	      }
224	      return counts;
225	    },
226	    { total: 0, completed: 0, in_progress: 0, pending: 0, blocked: 0 }
227	  );
228	}
