 88		// AC: @ui-session-stream ac-2 — Periodic structured refresh for live sessions
 89		async function refreshEvents() {
 90			if (!isLive) return;
 91			try {
 92				const eventsData = await fetchSessionEvents(sessionId, lastSeq);
 93				if (eventsData.events.length > 0) {
 94					events = [...events, ...eventsData.events];
 95					blocks = parseEventsToBlocks(events);
 96					lastSeq = getLastSeq(events);
 97					// Clear streaming text when we get structured data
 98					streamingText = '';
 99				}
100	
101				// Also refresh session metadata to detect status changes
102				const sessionData = await fetchSession(sessionId);
103				session = sessionData;
104			} catch {
105				// Ignore refresh errors — will retry on next interval
106			}
107		}
108	
109		// AC: @ui-session-stream ac-2 — WebSocket handler for live text chunks
110		function handleAgentEvent(event: BroadcastEvent) {
111			// Uses extracted utility for session-filtered text accumulation
112			streamingText = accumulateStreamingText(streamingText, event, sessionId);
113	
114			if (event.event === 'agent_invocation') {
115				const data = event.data as { session_id?: string; status?: string };
116				if (data.session_id === sessionId) {
117					// Refresh on invocation state changes
118					refreshEvents();
119				}
120			}
121		}
122	
123		onMount(() => {
124			loadSession();
125	
126			// Subscribe to agent events for live streaming
127			if (!isStaticMode()) {
128				subscribe(['agents']);
129				on('agents', handleAgentEvent);
130			}
131	
132			// AC: @ui-session-stream ac-2 — Periodic refresh (every 3s for live sessions)
133			if (!isStaticMode()) {
134				refreshTimer = setInterval(() => {
135					if (isLive) {
136						refreshEvents();
137					}
138				}, 3000);
139			}
140		});
141	
142		onDestroy(() => {
143			if (!isStaticMode()) {
144				off('agents', handleAgentEvent);
145				unsubscribe(['agents']);
146			}
147			if (refreshTimer) clearInterval(refreshTimer);
148		});
