165						<span class="font-mono text-sm text-muted-foreground ml-1">{session.id.slice(0, 8)}</span>
166					{/if}
167				</h1>
168				{#if session}
169					<p class="text-xs text-muted-foreground">
170						{session.agent_type}
171						{#if isLive}
172							<span class="ds-session-active-dot size-1.5 rounded-full bg-status-completed inline-block ml-1"></span>
173							<span class="text-status-completed">Live</span>
174						{/if}
