  1	<!--
  2	  AC: @ui-settings-view ac-1 — Displays project config (name, version, remote tracking),
  3	  conventions list from meta, daemon connection info (port, uptime, version), and shadow branch
  4	  status. Read-only for v1.
  5	-->
  6	<script lang="ts">
  7		import { onMount, onDestroy } from 'svelte';
  8		import type { Convention } from '@kynetic-ai/shared';
  9		import {
 10			fetchHealth,
 11			fetchProjectConfig,
 12			fetchShadowStatus,
 13			fetchConventions,
 14			type HealthResponse,
 15			type ProjectConfig,
 16			type ShadowStatusResponse
 17		} from '$lib/api';
 18		import { getSnapshot, isStaticMode } from '$lib/stores/mode.svelte';
 19		import { subscribe, unsubscribe, on, off } from '$lib/stores/connection.svelte';
 20		import { getProjectVersion, isInitialized as isProjectInitialized } from '$lib/stores/project.svelte';
 21		import { Card, CardContent, CardHeader } from '$lib/components/ui/card';
 22		import { Badge } from '$lib/components/ui/badge';
 23		import ServerIcon from '@lucide/svelte/icons/server';
 24		import GitBranchIcon from '@lucide/svelte/icons/git-branch';
 25		import BookOpenIcon from '@lucide/svelte/icons/book-open';
 26		import FolderIcon from '@lucide/svelte/icons/folder';
 27		import ChevronDownIcon from '@lucide/svelte/icons/chevron-down';
 28		import ChevronRightIcon from '@lucide/svelte/icons/chevron-right';
 29	
 30		// ── Data state ──
 31		let health = $state<HealthResponse | null>(null);
 32		let projectConfig = $state<ProjectConfig | null>(null);
 33		let shadowStatus = $state<ShadowStatusResponse | null>(null);
 34		let conventions = $state<Convention[]>([]);
 35	
 36		let loadingConfig = $state(true);
 37		let loadingHealth = $state(true);
 38		let loadingShadow = $state(true);
 39		let loadingConventions = $state(true);
 40	
 41		let errorConfig = $state('');
 42		let errorHealth = $state('');
 43		let errorShadow = $state('');
 44		let errorConventions = $state('');
 45	
 46		// Convention expand state
 47		let expandedDomains = $state<Set<string>>(new Set());
 48	
 49		// ── Lifecycle ──
 50		onMount(() => {
 51			if (!isStaticMode()) {
 52				subscribe(['files:updates']);
 53				on('files:updates', handleUpdate);
 54			}
 55		});
 56	
 57		onDestroy(() => {
 58			if (!isStaticMode()) {
 59				off('files:updates', handleUpdate);
 60				unsubscribe(['files:updates']);
 61			}
 62		});
 63	
 64		// Load data when project is ready and reload on project change.
 65		// Gates on isProjectInitialized() to prevent loading with wrong/missing project context.
 66		$effect(() => {
 67			const version = getProjectVersion();
 68			const ready = isProjectInitialized();
 69			if (!ready) return;
 70			loadAllData();
 71		});
 72	
 73		// ── Data loading ──
 74		async function loadAllData() {
 75			await Promise.all([loadConfig(), loadHealth(), loadShadow(), loadConventions()]);
 76		}
 77	
 78		async function loadConfig() {
 79			if (isStaticMode()) {
 80				const snapshot = getSnapshot();
 81				projectConfig = {
 82					project: {
 83						name: snapshot?.project.name ?? 'Static Export',
 84						version: snapshot?.project.version ?? '—',
 85						status: 'static'
 86					},
 87					spec_version: null,
 88					root_dir: 'GitHub Pages export',
 89					remote_tracking: null,
 90					daemon: { port: 0, host: 'n/a', auto_start: false }
 91				};
 92				loadingConfig = false;
 93				return;
 94			}
 95			try {
 96				loadingConfig = true;
 97				errorConfig = '';
 98				projectConfig = await fetchProjectConfig();
 99			} catch (err) {
100				errorConfig = err instanceof Error ? err.message : 'Failed to load project config';
101			} finally {
102				loadingConfig = false;
103			}
104		}
105	
106		async function loadHealth() {
107			if (isStaticMode()) {
108				loadingHealth = false;
109				return;
110			}
111			try {
112				loadingHealth = true;
113				errorHealth = '';
114				health = await fetchHealth();
115			} catch (err) {
116				errorHealth = err instanceof Error ? err.message : 'Failed to connect to daemon';
117			} finally {
118				loadingHealth = false;
119			}
120		}
121	
122		async function loadShadow() {
123			if (isStaticMode()) {
124				loadingShadow = false;
125				return;
126			}
127			try {
128				loadingShadow = true;
129				errorShadow = '';
130				shadowStatus = await fetchShadowStatus();
131			} catch (err) {
132				errorShadow = err instanceof Error ? err.message : 'Failed to load shadow status';
133			} finally {
134				loadingShadow = false;
135			}
136		}
137	
138		async function loadConventions() {
139			if (isStaticMode()) {
140				conventions = getSnapshot()?.conventions ?? [];
141				loadingConventions = false;
142				return;
143			}
144			try {
145				loadingConventions = true;
146				errorConventions = '';
147				const response = await fetchConventions();
148				conventions = response.items;
149			} catch (err) {
150				errorConventions = err instanceof Error ? err.message : 'Failed to load conventions';
151			} finally {
152				loadingConventions = false;
153			}
154		}
155	
156		function handleUpdate() {
157			loadAllData();
158		}
159	
160		// ── Helpers ──
161		function formatUptime(seconds: number): string {
162			const h = Math.floor(seconds / 3600);
163			const m = Math.floor((seconds % 3600) / 60);
164			const s = Math.floor(seconds % 60);
165			if (h > 0) return `${h}h ${m}m ${s}s`;
166			if (m > 0) return `${m}m ${s}s`;
167			return `${s}s`;
168		}
169	
170		function toggleDomain(domain: string) {
171			const next = new Set(expandedDomains);
172			if (next.has(domain)) {
173				next.delete(domain);
174			} else {
175				next.add(domain);
176			}
177			expandedDomains = next;
178		}
179	
180		let loading = $derived(loadingConfig && loadingHealth && loadingShadow && loadingConventions);
181	</script>
182	
183	<div class="flex flex-col gap-4 p-6">
184		<!-- Header -->
185		<div class="flex items-center justify-between">
186			<div>
187				<h1 class="text-2xl font-bold">Settings</h1>
188				{#if !loading}
189					<p class="text-sm text-muted-foreground" data-testid="settings-summary">
190						Project configuration and daemon status
191					</p>
192				{/if}
193			</div>
194		</div>
195	
196		<div class="grid gap-4 md:grid-cols-2">
197				<!-- ═══ Section 1: Project Configuration ═══ -->
198				<Card data-testid="settings-project-config">
199					<CardHeader class="pb-3">
200						<div class="flex items-center gap-2">
201							<FolderIcon class="size-4 text-muted-foreground" />
202							<h2 class="text-sm font-semibold">Project Configuration</h2>
203						</div>
204					</CardHeader>
205					<CardContent class="pt-0">
206						{#if loadingConfig}
207							<div class="flex flex-col gap-2" data-testid="settings-project-loading">
208								<div class="h-4 w-3/4 rounded bg-muted ds-shimmer"></div>
209								<div class="h-4 w-1/2 rounded bg-muted ds-shimmer"></div>
210								<div class="h-4 w-2/3 rounded bg-muted ds-shimmer"></div>
211							</div>
212						{:else if errorConfig}
213							<div class="text-sm text-destructive" data-testid="settings-project-error" role="alert">
214								{errorConfig}
215							</div>
216						{:else if projectConfig}
217							<dl class="flex flex-col gap-2 text-sm">
218								<div class="flex justify-between">
219									<dt class="text-muted-foreground">Name</dt>
220									<dd class="font-medium" data-testid="config-project-name">
221										{projectConfig.project?.name ?? 'Not configured'}
222									</dd>
223								</div>
224								<div class="flex justify-between">
225									<dt class="text-muted-foreground">Version</dt>
226									<dd class="font-mono text-xs" data-testid="config-project-version">
227										{projectConfig.project?.version ?? '—'}
228									</dd>
229								</div>
230								<div class="flex justify-between">
231									<dt class="text-muted-foreground">Status</dt>
232									<dd data-testid="config-project-status">
233										<Badge variant="secondary" class="text-xs">
234											{projectConfig.project?.status ?? '—'}
235										</Badge>
236									</dd>
237								</div>
238								<div class="flex justify-between">
239									<dt class="text-muted-foreground">Spec Version</dt>
240									<dd class="font-mono text-xs" data-testid="config-spec-version">
241										{projectConfig.spec_version ?? '—'}
242									</dd>
243								</div>
